import{_ as e,o as l,c as d,a0 as a}from"./chunks/framework.DQOulFGV.js";const g=JSON.parse('{"title":"第4章 开发运维陷阱","description":"","frontmatter":{},"headers":[],"relativePath":"redis/05-operations/chapter-04-pitfalls.md","filePath":"redis/05-operations/chapter-04-pitfalls.md"}'),i={name:"redis/05-operations/chapter-04-pitfalls.md"};function s(n,t,r,y,f,x){return l(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="第4章-开发运维陷阱" tabindex="-1">第4章 开发运维陷阱 <a class="header-anchor" href="#第4章-开发运维陷阱" aria-label="Permalink to &quot;第4章 开发运维陷阱&quot;">​</a></h1><blockquote><p>Redis 踩坑大多来自「命令误用」与「配置不当」。本章汇总开发、运维、集群三方面的常见陷阱，并提供上线前检查清单。</p></blockquote><hr><h2 id="_4-1-开发陷阱" tabindex="-1">4.1 开发陷阱 <a class="header-anchor" href="#_4-1-开发陷阱" aria-label="Permalink to &quot;4.1 开发陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">陷阱</th><th style="text-align:left;">问题</th><th style="text-align:left;">正确做法</th></tr></thead><tbody><tr><td style="text-align:left;"><code>KEYS *</code></td><td style="text-align:left;">全量遍历阻塞主线程</td><td style="text-align:left;">用 <code>SCAN</code> 游标分批</td></tr><tr><td style="text-align:left;"><code>DEL</code> 大 Key</td><td style="text-align:left;">同步删除阻塞</td><td style="text-align:left;">用 <code>UNLINK</code> 异步删除</td></tr><tr><td style="text-align:left;"><code>HGETALL</code> 大 Hash</td><td style="text-align:left;">一次返回全部字段</td><td style="text-align:left;">用 <code>HSCAN</code> 分批</td></tr><tr><td style="text-align:left;">String 存整块 JSON</td><td style="text-align:left;">更新需全量覆盖</td><td style="text-align:left;">用 Hash 存字段</td></tr><tr><td style="text-align:left;">无 TTL 缓存</td><td style="text-align:left;">key 永久堆积</td><td style="text-align:left;">设置合理 TTL</td></tr><tr><td style="text-align:left;">短连接</td><td style="text-align:left;">反复 TCP 握手</td><td style="text-align:left;">使用连接池 + 长连接</td></tr></tbody></table><hr><h2 id="_4-2-运维陷阱" tabindex="-1">4.2 运维陷阱 <a class="header-anchor" href="#_4-2-运维陷阱" aria-label="Permalink to &quot;4.2 运维陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">陷阱</th><th style="text-align:left;">问题</th><th style="text-align:left;">正确做法</th></tr></thead><tbody><tr><td style="text-align:left;">主节点不持久化</td><td style="text-align:left;">主从切换后数据丢失</td><td style="text-align:left;">主节点必须开持久化</td></tr><tr><td style="text-align:left;">不设 maxmemory</td><td style="text-align:left;">内存涨到 OOM</td><td style="text-align:left;">设上限 + 淘汰策略</td></tr><tr><td style="text-align:left;">内存超物理上限</td><td style="text-align:left;">触发 swap，性能骤降</td><td style="text-align:left;">预留内存余量</td></tr><tr><td style="text-align:left;">透明大页</td><td style="text-align:left;">fork 性能下降</td><td style="text-align:left;">关闭 THP（transparent huge pages）</td></tr><tr><td style="text-align:left;">单核绑定</td><td style="text-align:left;">子进程与主进程抢 CPU</td><td style="text-align:left;">不绑定单核</td></tr><tr><td style="text-align:left;"><code>appendfsync always</code></td><td style="text-align:left;">性能大幅下降</td><td style="text-align:left;">非强一致用 everysec</td></tr></tbody></table><hr><h2 id="_4-3-集群陷阱" tabindex="-1">4.3 集群陷阱 <a class="header-anchor" href="#_4-3-集群陷阱" aria-label="Permalink to &quot;4.3 集群陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">陷阱</th><th style="text-align:left;">问题</th><th style="text-align:left;">正确做法</th></tr></thead><tbody><tr><td style="text-align:left;">跨槽多 key 命令</td><td style="text-align:left;">MGET/事务/Lua 报错</td><td style="text-align:left;">用哈希标签 <code>{}</code> 强制同槽</td></tr><tr><td style="text-align:left;">集群倾斜</td><td style="text-align:left;">热 key 集中某一分片</td><td style="text-align:left;">本地缓存、key 复制分散</td></tr><tr><td style="text-align:left;">大 Key 迁移</td><td style="text-align:left;">扩容迁移慢</td><td style="text-align:left;">拆分大 Key</td></tr><tr><td style="text-align:left;">带宽消耗</td><td style="text-align:left;">Gossip 通信占用带宽</td><td style="text-align:left;">合理规划节点规模</td></tr><tr><td style="text-align:left;">读写分离滥用</td><td style="text-align:left;">读到旧数据</td><td style="text-align:left;">强一致需求别用从节点读</td></tr></tbody></table><hr><h2 id="_4-4-上线检查清单" tabindex="-1">4.4 上线检查清单 <a class="header-anchor" href="#_4-4-上线检查清单" aria-label="Permalink to &quot;4.4 上线检查清单&quot;">​</a></h2><p>上线前逐项确认：</p><table tabindex="0"><thead><tr><th style="text-align:left;">类别</th><th style="text-align:left;">检查项</th></tr></thead><tbody><tr><td style="text-align:left;">内存</td><td style="text-align:left;"><code>maxmemory</code> 已设且留有余量</td></tr><tr><td style="text-align:left;">淘汰</td><td style="text-align:left;"><code>maxmemory-policy</code> 符合业务（非 noeviction）</td></tr><tr><td style="text-align:left;">持久化</td><td style="text-align:left;">主节点开启持久化，fsync 策略合理</td></tr><tr><td style="text-align:left;">过期</td><td style="text-align:left;">缓存 key 都设置了 TTL</td></tr><tr><td style="text-align:left;">命令</td><td style="text-align:left;">无 KEYS、大 DEL 等危险命令</td></tr><tr><td style="text-align:left;">连接</td><td style="text-align:left;">客户端使用连接池，连接数可控</td></tr><tr><td style="text-align:left;">监控</td><td style="text-align:left;">内存、延迟、命中率已接入监控告警</td></tr><tr><td style="text-align:left;">高可用</td><td style="text-align:left;">哨兵/集群已配置，故障转移可验证</td></tr></tbody></table><blockquote><p>上线前的检查清单不是形式，而是把「踩过的坑」固化下来，避免重复犯错。</p></blockquote>',16)])])}const h=e(i,[["render",s]]);export{g as __pageData,h as default};
